'use client';

import React, { createContext, useContext } from 'react';
import { usePathname, useRouter } from 'next/navigation';
import { Lock, Sparkles, LogOut, CreditCard } from 'lucide-react';

interface SubscriptionContextType {
    isSubscribed: boolean;
    subscriptionEnd: string | null;
    hasExpired: boolean;
    plan: string | null;
    isTrial: boolean;
}

const SubscriptionContext = createContext<SubscriptionContextType>({
    isSubscribed: false,
    subscriptionEnd: null,
    hasExpired: true,
    plan: null,
    isTrial: true,
});

export const useSubscription = () => useContext(SubscriptionContext);

interface SubscriptionGuardProps {
    children: React.ReactNode;
    isSubscribed: boolean;
    subscriptionEnd: string | null;
    hasExpired: boolean;
    plan: string | null;
}

export default function SubscriptionGuard({
    children,
    isSubscribed,
    subscriptionEnd,
    hasExpired,
    plan,
}: SubscriptionGuardProps) {
    const pathname = usePathname();
    const router = useRouter();

    const isTrial = !isSubscribed || hasExpired;

    // Allow access to the payment page without restriction
    if (pathname === '/dashboard/payment') {
        return <>{children}</>;
    }

    const handleLogout = async () => {
        // Clear student session cookie by calling standard logout or simply setting cookie expire
        document.cookie = 'student_session=; Path=/; Expires=Thu, 01 Jan 1970 00:00:01 GMT;';
        router.push('/login');
    };

    const isIeltsRoute =
        pathname.startsWith('/dashboard/reading') ||
        pathname.startsWith('/dashboard/listening') ||
        pathname.startsWith('/dashboard/writing') ||
        pathname.startsWith('/dashboard/speaking') ||
        pathname.startsWith('/dashboard/band-predictor') ||
        pathname.startsWith('/dashboard/mock');

    // If they have spoken plan but try to access IELTS route, block and ask to upgrade (even in trial/premium)
    if (plan === 'spoken' && isIeltsRoute) {
        return (
            <div className="min-h-screen bg-gradient-to-br from-slate-950 via-slate-900 to-indigo-950 flex items-center justify-center px-4 relative overflow-hidden">
                <div className="absolute top-1/4 left-1/4 w-96 h-96 bg-indigo-500/10 rounded-full blur-3xl" />
                <div className="absolute bottom-1/4 right-1/4 w-96 h-96 bg-pink-500/5 rounded-full blur-3xl" />

                <div className="w-full max-w-lg relative z-10">
                    <div className="bg-slate-900/70 backdrop-blur-2xl border border-slate-800/80 rounded-3xl p-8 shadow-2xl text-center">
                        <div className="flex justify-center mb-6">
                            <div className="relative">
                                <div className="absolute -inset-1 rounded-full bg-gradient-to-tr from-pink-600 to-indigo-500 blur opacity-40 animate-pulse" />
                                <div className="relative flex h-16 w-16 items-center justify-center rounded-full bg-slate-950 border border-slate-800 text-indigo-400">
                                    <Lock size={28} />
                                </div>
                            </div>
                        </div>

                        <span className="inline-flex items-center gap-1.5 rounded-full border border-indigo-500/30 bg-indigo-500/10 px-3 py-1 text-[10px] font-black uppercase tracking-widest text-indigo-300 mb-4">
                            <Sparkles size={10} />
                            Upgrade Plan Required
                        </span>

                        <h2 className="text-2xl font-black text-white tracking-tight mb-3">
                            IELTS ফিচার ব্যবহার করতে আপগ্রেড করো!
                        </h2>

                        <p className="text-sm text-slate-300 leading-relaxed mb-6 font-medium">
                            তোমার অ্যাকাউন্টে বর্তমানে শুধুমাত্র **Spoken English Pro** প্ল্যানটি সক্রিয় আছে। IELTS-এর রিডিং, লিসেনিং, রাইটিং, স্পিকিং এবং মক টেস্ট ফিচারগুলো ব্যবহার করতে দয়া করে তোমার সাবস্ক্রিপশন প্ল্যানটি **IELTS + Spoken English**-এ আপগ্রেড করো।
                        </p>

                        <div className="grid gap-3 sm:grid-cols-2">
                            <button
                                onClick={() => router.push('/dashboard/payment?required=ielts_spoken')}
                                className="flex items-center justify-center gap-2 rounded-xl bg-gradient-to-r from-pink-600 to-indigo-600 px-5 py-3 text-sm font-bold text-white hover:from-pink-500 hover:to-indigo-500 transition shadow-lg shadow-pink-500/20"
                            >
                                <CreditCard size={16} /> Plan আপগ্রেড করো
                            </button>

                            <button
                                onClick={() => router.push('/dashboard')}
                                className="flex items-center justify-center gap-2 rounded-xl border border-slate-800 bg-slate-950/60 px-5 py-3 text-sm font-bold text-slate-400 hover:text-white hover:bg-slate-900 transition"
                            >
                                ড্যাশবোর্ডে ফিরে যাও
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        );
    }

    return (
        <SubscriptionContext.Provider value={{ isSubscribed, subscriptionEnd, hasExpired, plan, isTrial }}>
            {/* Top Alert Banner for Free Trial / Guest Mode */}
            {isTrial && (
                <div className="bg-gradient-to-r from-amber-600 via-indigo-900 to-amber-700 text-white px-4 py-2.5 text-center text-xs font-bold flex flex-wrap items-center justify-center gap-3 relative z-50 shadow-md border-b border-indigo-950">
                    <span className="bg-amber-400/20 border border-amber-300/30 rounded-md px-1.5 py-0.5 text-[9px] font-black uppercase tracking-wider text-amber-300 animate-pulse">
                        Free Trial / Demo Mode
                    </span>
                    <span className="text-slate-200">
                        {hasExpired 
                          ? 'তোমার সাবস্ক্রিপশনের মেয়াদ শেষ হয়ে গেছে! ফ্রি মোডে কেমব্রিজ টেস্ট ৯-১৫ ও গ্রামার প্র্যাকটিস করতে পারবে।' 
                          : 'তুমি বর্তমানে ফ্রি ট্রায়াল মোডে আছো। কেমব্রিজ ১৬-২০ ও আনলিমিটেড এআই ফিচার আনলক করতে সাবস্ক্রিপশন নাও।'}
                    </span>
                    <button 
                        onClick={() => router.push('/dashboard/payment')}
                        className="bg-gradient-to-r from-amber-400 to-amber-500 text-slate-950 px-3 py-1 rounded-lg font-black hover:brightness-110 transition text-[10px] shadow-sm"
                    >
                        Upgrade Now ↗
                    </button>
                </div>
            )}
            {children}
        </SubscriptionContext.Provider>
    );
}
